-- BibleQuest production upgrade v1: ministry media, inbox, recognition, calendar,
-- advanced assignments/polls, diagnostics and private learning profile.
alter table public.bible_ministry_messages add column if not exists media_path text;
alter table public.bible_ministry_messages add column if not exists media_alt text;
alter table public.bible_ministry_messages add column if not exists media_kind text not null default 'none';
alter table public.bible_ministry_messages add column if not exists pinned boolean not null default false;
alter table public.bible_ministry_messages add column if not exists audience_scope text not null default 'all';
alter table public.bible_assignments add column if not exists schedule_at timestamptz;
alter table public.bible_assignments add column if not exists recurrence_rule text;
alter table public.bible_assignments add column if not exists reminder_at timestamptz;
alter table public.bible_assignments add column if not exists required_reflection boolean not null default false;
alter table public.bible_assignments add column if not exists min_quiz_score integer;
alter table public.bible_assignments add column if not exists evidence_type text not null default 'none';
alter table public.bible_assignments add column if not exists linked_activity jsonb not null default '{}'::jsonb;
alter table public.bible_polls add column if not exists poll_type text not null default 'single';
alter table public.bible_polls add column if not exists results_visibility text not null default 'live';
alter table public.bible_polls add column if not exists anonymous_results boolean not null default true;
alter table public.bible_polls add column if not exists scheduled_at timestamptz;
create table if not exists public.bible_poll_responses(poll_id uuid not null references public.bible_polls(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,response jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(poll_id,user_id));
create table if not exists public.bible_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,congregation_id uuid references public.bible_congregations(id) on delete cascade,created_by uuid references auth.users(id) on delete set null,notification_type text not null default 'info',title text not null,body text not null default '',action_kind text,action_payload jsonb not null default '{}'::jsonb,read_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.bible_member_recognitions(id uuid primary key default gen_random_uuid(),congregation_id uuid not null references public.bible_congregations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,awarded_by uuid references auth.users(id) on delete set null,award_code text not null,title text not null,note text,icon text not null default '🏅',visible boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.bible_ministry_calendar(id uuid primary key default gen_random_uuid(),congregation_id uuid not null references public.bible_congregations(id) on delete cascade,created_by uuid references auth.users(id) on delete set null,event_type text not null default 'activity',title text not null,description text not null default '',starts_at timestamptz not null,ends_at timestamptz,linked_type text,linked_id uuid,location_text text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.bible_client_errors(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete set null,congregation_id uuid references public.bible_congregations(id) on delete set null,app_version text,surface text,message text not null,stack text,context jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.bible_user_learning_profile(user_id uuid primary key references auth.users(id) on delete cascade,weak_topics jsonb not null default '{}'::jsonb,reasoning_tendencies jsonb not null default '{}'::jsonb,preferred_depth text not null default 'balanced',updated_at timestamptz not null default now());
create table if not exists public.bible_content_escalations(id uuid primary key default gen_random_uuid(),congregation_id uuid not null references public.bible_congregations(id) on delete cascade,content_key text not null,raised_by uuid references auth.users(id) on delete set null,assigned_role text not null default 'pastor',note text,status text not null default 'open',resolved_by uuid references auth.users(id) on delete set null,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(congregation_id,content_key,status));
create table if not exists public.bible_account_deletion_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,reason text,status text not null default 'open',requested_at timestamptz not null default now(),resolved_at timestamptz,resolved_by uuid references auth.users(id) on delete set null);

alter table public.bible_poll_responses enable row level security;alter table public.bible_notifications enable row level security;alter table public.bible_member_recognitions enable row level security;alter table public.bible_ministry_calendar enable row level security;alter table public.bible_client_errors enable row level security;alter table public.bible_user_learning_profile enable row level security;alter table public.bible_content_escalations enable row level security;alter table public.bible_account_deletion_requests enable row level security;

drop policy if exists "poll responses own read" on public.bible_poll_responses;create policy "poll responses own read" on public.bible_poll_responses for select to authenticated using(user_id=auth.uid());
drop policy if exists "poll responses own insert" on public.bible_poll_responses;create policy "poll responses own insert" on public.bible_poll_responses for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.bible_polls p where p.id=poll_id and p.active and private.is_bible_congregation_member(p.congregation_id)));
drop policy if exists "poll responses own update" on public.bible_poll_responses;create policy "poll responses own update" on public.bible_poll_responses for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "notifications own read" on public.bible_notifications;create policy "notifications own read" on public.bible_notifications for select to authenticated using(user_id=auth.uid());
drop policy if exists "notifications own update" on public.bible_notifications;create policy "notifications own update" on public.bible_notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "leaders create notifications" on public.bible_notifications;create policy "leaders create notifications" on public.bible_notifications for insert to authenticated with check(created_by=auth.uid() and congregation_id is not null and private.bible_role_in_congregation(congregation_id)=any(array['facilitator','leader','pastor','admin']) and exists(select 1 from public.bible_congregation_members m where m.congregation_id=bible_notifications.congregation_id and m.user_id=bible_notifications.user_id and m.active));
drop policy if exists "recognitions congregation read" on public.bible_member_recognitions;create policy "recognitions congregation read" on public.bible_member_recognitions for select to authenticated using(visible and private.is_bible_congregation_member(congregation_id));
drop policy if exists "leaders create recognitions" on public.bible_member_recognitions;create policy "leaders create recognitions" on public.bible_member_recognitions for insert to authenticated with check(awarded_by=auth.uid() and private.bible_role_in_congregation(congregation_id)=any(array['leader','pastor','admin']));
drop policy if exists "calendar congregation read" on public.bible_ministry_calendar;create policy "calendar congregation read" on public.bible_ministry_calendar for select to authenticated using(active and private.is_bible_congregation_member(congregation_id));
drop policy if exists "leaders create calendar" on public.bible_ministry_calendar;create policy "leaders create calendar" on public.bible_ministry_calendar for insert to authenticated with check(created_by=auth.uid() and private.bible_role_in_congregation(congregation_id)=any(array['facilitator','leader','pastor','admin']));
drop policy if exists "users report own client errors" on public.bible_client_errors;create policy "users report own client errors" on public.bible_client_errors for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "learning profile own read" on public.bible_user_learning_profile;create policy "learning profile own read" on public.bible_user_learning_profile for select to authenticated using(user_id=auth.uid());
drop policy if exists "learning profile own insert" on public.bible_user_learning_profile;create policy "learning profile own insert" on public.bible_user_learning_profile for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "learning profile own update" on public.bible_user_learning_profile;create policy "learning profile own update" on public.bible_user_learning_profile for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "reviewers read escalations" on public.bible_content_escalations;create policy "reviewers read escalations" on public.bible_content_escalations for select to authenticated using(private.bible_role_in_congregation(congregation_id)=any(array['leader','pastor','admin']));
drop policy if exists "reviewers create escalations" on public.bible_content_escalations;create policy "reviewers create escalations" on public.bible_content_escalations for insert to authenticated with check(raised_by=auth.uid() and private.bible_role_in_congregation(congregation_id)=any(array['leader','pastor','admin']));
drop policy if exists "pastor admin update escalations" on public.bible_content_escalations;create policy "pastor admin update escalations" on public.bible_content_escalations for update to authenticated using(private.bible_role_in_congregation(congregation_id)=any(array['pastor','admin'])) with check(private.bible_role_in_congregation(congregation_id)=any(array['pastor','admin']));
drop policy if exists "deletion requests own read" on public.bible_account_deletion_requests;create policy "deletion requests own read" on public.bible_account_deletion_requests for select to authenticated using(user_id=auth.uid());
drop policy if exists "deletion requests own insert" on public.bible_account_deletion_requests;create policy "deletion requests own insert" on public.bible_account_deletion_requests for insert to authenticated with check(user_id=auth.uid());

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('biblequest-announcements','biblequest-announcements',false,5242880,array['image/jpeg','image/png','image/webp','image/gif']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp','image/gif'];
drop policy if exists "announcement media congregation read" on storage.objects;create policy "announcement media congregation read" on storage.objects for select to authenticated using(bucket_id='biblequest-announcements' and private.is_bible_congregation_member((split_part(name,'/',1))::uuid));
drop policy if exists "announcement media leader insert" on storage.objects;create policy "announcement media leader insert" on storage.objects for insert to authenticated with check(bucket_id='biblequest-announcements' and private.bible_role_in_congregation((split_part(name,'/',1))::uuid)=any(array['facilitator','leader','pastor','admin']));
drop policy if exists "announcement media leader delete" on storage.objects;create policy "announcement media leader delete" on storage.objects for delete to authenticated using(bucket_id='biblequest-announcements' and private.bible_role_in_congregation((split_part(name,'/',1))::uuid)=any(array['facilitator','leader','pastor','admin']));
create index if not exists bible_notifications_user_created_idx on public.bible_notifications(user_id,created_at desc);create index if not exists bible_recognitions_congregation_created_idx on public.bible_member_recognitions(congregation_id,created_at desc);create index if not exists bible_calendar_congregation_start_idx on public.bible_ministry_calendar(congregation_id,starts_at);create index if not exists bible_client_errors_created_idx on public.bible_client_errors(created_at desc);create index if not exists bible_content_escalations_queue_idx on public.bible_content_escalations(congregation_id,status,created_at desc);create unique index if not exists bible_deletion_request_one_open on public.bible_account_deletion_requests(user_id) where status='open';